<?php declare(strict_types=1); ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Habilidades — ZystemWorkSpace</title><style>:root{font:15px system-ui;color:#e8eef7;background:#080d14}body{margin:0;padding:28px;max-width:1050px}main{max-width:1050px;margin:auto}.hero,.panel,.skill-card{background:linear-gradient(145deg,#101a28,#0d1622);border:1px solid #263b56;border-radius:16px;padding:20px;box-shadow:0 16px 40px #0002}.hero{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:16px}.hero h1{margin:0 0 7px;font-size:28px}.muted{color:#91a5bd;line-height:1.5}.actions{display:flex;gap:8px;flex-wrap:wrap}.button,button{font:inherit;padding:10px 13px;border-radius:9px;border:1px solid #385474;background:#193b5d;color:#fff;cursor:pointer}.button:hover,button:hover{background:#25527c}input,textarea{width:100%;box-sizing:border-box;padding:10px;margin:5px 0 11px;border:1px solid #385474;border-radius:8px;background:#0a1420;color:#fff;font:inherit}label{display:block;color:#b9cbe0;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.skill-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px}.skill-card{padding:16px}.skill-card h3{font-size:15px;margin:0 0 7px;color:#eaf3ff}.skill-card p{min-height:44px;color:#9fb1c6;font-size:13px;line-height:1.45}.badge{display:inline-flex;padding:4px 8px;border-radius:99px;font-size:11px}.on{background:#143b2d;color:#8ee0ad}.off{background:#3b2f17;color:#ffd786}.skill-card footer{display:flex;justify-content:space-between;align-items:center;gap:8px}.status{min-height:24px;color:#9fe0b0;margin:10px 0}.error{color:#ff9d9d}.progress{display:none;height:8px;background:#18283b;border-radius:99px;overflow:hidden;margin:10px 0}.progress i{display:block;height:100%;width:0;background:linear-gradient(90deg,#6da7ff,#8ee0ad);transition:width .15s}.small{font-size:12px}.toplinks{color:#9fb4ca;margin-bottom:14px}.toplinks a{color:#bcd8ff}@media(max-width:700px){body{padding:18px}.hero{display:block}.grid{grid-template-columns:1fr}}
</style></head><body><?php require __DIR__ . '/menu.php'; ?><main><div class="toplinks"><a href="index.php">Chat</a> · <a href="plugins.php">Plugins</a> · <a href="settings.php">Configurações</a></div><section class="hero"><div><h1>Habilidades</h1><p class="muted">Ative orientações especializadas para o agente ou instale pacotes completos no formato <b>SKILL.md</b>.</p></div><div class="actions"><button id="seed">Instalar catálogo recomendado</button></div></section><section class="panel"><h2>Instalar habilidade via ZIP</h2><p class="muted small">O ZIP deve conter exatamente um SKILL.md na raiz ou dentro de uma pasta. Referências Markdown, TXT e JSON são preservadas. O pacote começa desativado.</p><form id="zipform"><input type="file" name="skill_zip" accept=".zip,application/zip" required><button>Instalar ZIP</button></form><div class="progress" id="zipProgress"><i></i></div><div class="status" id="msg" aria-live="polite"></div></section><section class="panel"><h2>Adicionar habilidade manualmente</h2><form id="add"><div class="grid"><label>Nome<input name="name" required pattern="[A-Za-z0-9._-]{2,80}" placeholder="minha-habilidade"></label><label>Descrição<input name="description" required placeholder="O que essa habilidade faz"></label></div><label>Instruções<textarea name="prompt" required rows="5" placeholder="Como o agente deve trabalhar..."></textarea></label><button>Adicionar habilidade</button></form></section><section class="panel"><h2>Catálogo instalado</h2><div id="list" class="skill-grid">Carregando...</div></section></main><script>const list=document.querySelector('#list'),msg=document.querySelector('#msg'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(url,opt){const r=await fetch(url,opt),d=await r.json();if(!d.ok)throw Error(d.error||'Falha na operação');return d}async function load(){try{const d=await api('../api/skills.php');list.innerHTML=d.items.map(x=>`<article class="skill-card"><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><footer><span class="badge ${x.enabled?'on':'off'}">${x.enabled?'Ativada':'Desativada'}</span><button data-name="${esc(x.name)}" data-on="${x.enabled?'1':'0'}">${x.enabled?'Desativar':'Ativar'}</button></footer></article>`).join('')||'Nenhuma habilidade instalada.'}catch(e){list.innerHTML='<span class="error">'+esc(e.message)+'</span>'}}list.onclick=async e=>{const b=e.target.closest('button[data-name]');if(!b)return;try{await api('../api/skills.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:b.dataset.on==='1'?'disable':'enable',name:b.dataset.name})});msg.textContent='Estado atualizado.';load()}catch(x){msg.textContent=x.message;msg.className='status error'}};document.querySelector('#add').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('../api/skills.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'install',name:f.get('name'),description:f.get('description'),prompt:f.get('prompt')})});msg.textContent='Habilidade adicionada. Agora clique em Ativar.';msg.className='status';e.target.reset();load()}catch(x){msg.textContent=x.message;msg.className='status error'}};document.querySelector('#seed').onclick=async()=>{try{const d=await api('../api/skills.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'seed'})});msg.textContent=d.installed.length+' habilidades instaladas.';load()}catch(e){msg.textContent=e.message;msg.className='status error'}};document.querySelector('#zipform').onsubmit=e=>{e.preventDefault();const form=e.target,file=form.querySelector('input[type=file]').files[0],bar=document.querySelector('#zipProgress'),fill=bar.querySelector('i');if(!file)return;const xhr=new XMLHttpRequest();xhr.open('POST','../api/skills.php');xhr.upload.onprogress=e=>{if(e.lengthComputable){bar.style.display='block';fill.style.width=(e.loaded/e.total*100)+'%';msg.textContent='Enviando ZIP… '+Math.round(e.loaded/e.total*100)+'%'}};xhr.onload=()=>{try{const raw=xhr.responseText.trim();if(raw.startsWith('<'))throw Error('O servidor devolveu uma página HTML em vez de JSON. Reinicie pelo 2-INICIAR-TUDO.bat atualizado.');const d=JSON.parse(raw);if(!d.ok)throw Error(d.error||'O servidor recusou o ZIP.');msg.textContent='ZIP instalado: '+d.skill.name+'. Agora clique em Ativar.';form.reset();load()}catch(err){msg.textContent=err.message;msg.className='status error'}finally{setTimeout(()=>{bar.style.display='none';fill.style.width='0'},800)}};xhr.onerror=()=>{msg.textContent='Falha de rede durante o upload.';msg.className='status error'};const data=new FormData(form);data.append('action','upload_zip');bar.style.display='block';xhr.send(data)};load();</script></body></html>
